import{_ as e,o as t,c as a,ag as s}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"macOS Certificate Setup","description":"","frontmatter":{},"headers":[],"relativePath":"certificate/macos.md","filePath":"certificate/macos.md","lastUpdated":1772297611000}'),n={name:"certificate/macos.md"};function o(r,i,l,c,h,d){return t(),a("div",null,[...i[0]||(i[0]=[s(`<h1 id="macos-certificate-setup" tabindex="-1">macOS Certificate Setup <a class="header-anchor" href="#macos-certificate-setup" aria-label="Permalink to &quot;macOS Certificate Setup&quot;">​</a></h1><p>This guide explains how to install the NectoProxy root CA certificate on macOS so that HTTPS traffic can be intercepted without browser warnings.</p><h2 id="method-1-command-line-recommended" tabindex="-1">Method 1: Command Line (Recommended) <a class="header-anchor" href="#method-1-command-line-recommended" aria-label="Permalink to &quot;Method 1: Command Line (Recommended)&quot;">​</a></h2><p>Open Terminal and run the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-trusted-cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trustRoot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/Keychains/System.keychain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ~/.nectoproxy/certs/ca.pem</span></span></code></pre></div><p>You will be prompted for your administrator password. Once entered, the certificate is immediately trusted system-wide.</p><div class="tip custom-block"><p class="custom-block-title">What This Command Does</p><ul><li><code>security add-trusted-cert</code> -- Adds a certificate to a keychain and marks it as trusted.</li><li><code>-d</code> -- Adds the certificate to the admin trust settings (not just the user).</li><li><code>-r trustRoot</code> -- Marks it as a trusted root certificate.</li><li><code>-k /Library/Keychains/System.keychain</code> -- Installs it into the System keychain so all users on the machine trust it.</li></ul></div><h2 id="method-2-keychain-access-gui" tabindex="-1">Method 2: Keychain Access (GUI) <a class="header-anchor" href="#method-2-keychain-access-gui" aria-label="Permalink to &quot;Method 2: Keychain Access (GUI)&quot;">​</a></h2><p>If you prefer a graphical approach:</p><ol><li><p><strong>Open Keychain Access</strong></p><ul><li>Press <code>Cmd + Space</code>, type &quot;Keychain Access&quot;, and press Enter.</li><li>Or navigate to Applications &gt; Utilities &gt; Keychain Access.</li></ul></li><li><p><strong>Select the System keychain</strong></p><ul><li>In the left sidebar, click <strong>System</strong> under &quot;System Keychains&quot;.</li></ul></li><li><p><strong>Import the certificate</strong></p><ul><li>Go to File &gt; Import Items (or press <code>Shift + Cmd + I</code>).</li><li>Navigate to <code>~/.nectoproxy/certs/</code> and select <code>ca.pem</code>.</li><li>Click Open.</li></ul></li><li><p><strong>Trust the certificate</strong></p><ul><li>Find the newly imported certificate in the list (it will be named &quot;NectoProxy CA&quot; or similar).</li><li>Double-click the certificate to open its details.</li><li>Expand the <strong>Trust</strong> section.</li><li>Set <strong>When using this certificate</strong> to <strong>Always Trust</strong>.</li><li>Close the dialog. You will be prompted for your administrator password.</li></ul></li><li><p><strong>Confirm trust</strong></p><ul><li>The certificate should now show a blue &quot;+&quot; icon indicating it is trusted.</li></ul></li></ol><h2 id="verify-installation" tabindex="-1">Verify Installation <a class="header-anchor" href="#verify-installation" aria-label="Permalink to &quot;Verify Installation&quot;">​</a></h2><p>After installing the certificate, verify it is trusted:</p><h3 id="via-command-line" tabindex="-1">Via Command Line <a class="header-anchor" href="#via-command-line" aria-label="Permalink to &quot;Via Command Line&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find-certificate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;NectoProxy&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/Keychains/System.keychain</span></span></code></pre></div><p>If the certificate is found, the output will display its details.</p><h3 id="via-browser" tabindex="-1">Via Browser <a class="header-anchor" href="#via-browser" aria-label="Permalink to &quot;Via Browser&quot;">​</a></h3><ol><li>Open Safari or Chrome.</li><li>Make sure your proxy is set to <code>localhost:8888</code>.</li><li>Navigate to any HTTPS website (e.g., <code>https://example.com</code>).</li><li>The page should load without any certificate warnings.</li><li>Click the lock icon in the address bar to verify the certificate chain includes the NectoProxy CA.</li></ol><h2 id="removing-the-certificate" tabindex="-1">Removing the Certificate <a class="header-anchor" href="#removing-the-certificate" aria-label="Permalink to &quot;Removing the Certificate&quot;">​</a></h2><p>To remove the NectoProxy CA certificate when you no longer need it:</p><h3 id="via-command-line-1" tabindex="-1">Via Command Line <a class="header-anchor" href="#via-command-line-1" aria-label="Permalink to &quot;Via Command Line&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete-certificate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;NectoProxy&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/Keychains/System.keychain</span></span></code></pre></div><h3 id="via-keychain-access" tabindex="-1">Via Keychain Access <a class="header-anchor" href="#via-keychain-access" aria-label="Permalink to &quot;Via Keychain Access&quot;">​</a></h3><ol><li>Open Keychain Access.</li><li>Select the <strong>System</strong> keychain.</li><li>Find the NectoProxy CA certificate.</li><li>Right-click and select <strong>Delete</strong>.</li><li>Confirm deletion and enter your administrator password.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-certificate-is-not-trusted" tabindex="-1">&quot;The certificate is not trusted&quot; <a class="header-anchor" href="#the-certificate-is-not-trusted" aria-label="Permalink to &quot;&quot;The certificate is not trusted&quot;&quot;">​</a></h3><p>If you installed the certificate but browsers still show warnings:</p><ul><li><strong>Verify trust settings</strong>: Open the certificate in Keychain Access and confirm the Trust section shows &quot;Always Trust&quot;.</li><li><strong>Restart your browser</strong>: Some browsers cache certificate trust decisions. Close and reopen the browser completely.</li><li><strong>Check the keychain</strong>: Ensure the certificate is in the <strong>System</strong> keychain, not the <strong>login</strong> keychain. Certificates in the login keychain may not be trusted by all applications.</li></ul><h3 id="firefox-still-shows-warnings" tabindex="-1">Firefox Still Shows Warnings <a class="header-anchor" href="#firefox-still-shows-warnings" aria-label="Permalink to &quot;Firefox Still Shows Warnings&quot;">​</a></h3><p>Firefox uses its own certificate store and does not use the macOS System keychain by default. See the <a href="/nectoproxy/certificate/firefox.html">Firefox Certificate Setup</a> guide for Firefox-specific instructions.</p><h3 id="permission-denied" tabindex="-1">Permission Denied <a class="header-anchor" href="#permission-denied" aria-label="Permalink to &quot;Permission Denied&quot;">​</a></h3><p>If you get a permission error when running the <code>security</code> command:</p><ul><li>Make sure you are using <code>sudo</code>.</li><li>Verify your user account has administrator privileges.</li></ul><div class="warning custom-block"><p class="custom-block-title">Corporate / MDM Managed Macs</p><p>On managed Macs with MDM profiles, the System keychain may be locked or restricted. Contact your IT administrator, or install the certificate in the <strong>login</strong> keychain instead (it will only be trusted for your user account):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-trusted-cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trustRoot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Keychains/login.keychain-db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ~/.nectoproxy/certs/ca.pem</span></span></code></pre></div></div>`,33)])])}const k=e(n,[["render",o]]);export{u as __pageData,k as default};
